"""Researched positions for the competitive U.S. House races (rated Toss-up, Tilt or
Lean by any forecaster): the main candidates in each. Writes data/research/house.json.

Where guides.vote has a nonpartisan guide for the district, positions come from it:
each stance tied to a vote, bill or statement, quotes in the candidate's words (read
Oct. 25, 2026). Elsewhere they come from the candidates' campaign sites, read the
same day, or from news reports (debates, interviews, profiles) when a site lists no
issues. Current members keep the positions from their recorded House votes; a
researched position wins where both answer the same question.

As in the automatic vote rules, a "no" vote on an omnibus bill (H.R. 1 of 2025) is
not read as a position on its parts, and nothing is inferred from party.

    py scripts/research/house_2026.py
"""

from common import P, article, guide, page, source, write

READ = "2026-10-25"


def gv(district, slug):
    """A guides.vote district guide. Each call names the evidence the guide gives."""
    return guide(f"2026 {district} U.S. House voters guide", f"https://guides.vote/guide/{slug}/", READ)


def site(title, url):
    """One page of a campaign site, read on READ. Each call names the section."""
    return lambda note: page(f"{title}: {note}", url, READ)


def nc_house_vote(year, rcs, date, what, member, vote):
    """A recorded vote in the North Carolina House, from ncleg.gov's roll-call transcript."""
    return source(f"N.C. House roll call {rcs} ({year}) on {what}: {member} voted {vote}",
                  f"https://www.ncleg.gov/Legislation/Votes/RollCallVoteTranscript/{year}/H/{rcs}", date, accessed=False)


def cand(cid, name, official, *rows):
    c = {"id": cid, "name": name, "positions": P(*rows)}
    if official:
        c["officialSite"] = official
    return c


